@SuppressWarnings("unchecked")
    protected StringArrayDeserializer(ValueDeserializer<?> deser,
            NullValueProvider nuller, Boolean unwrapSingle) {
        super(String[].class);
        _elementDeserializer = (ValueDeserializer<String>) deser;
        _nullProvider = nuller;
